command:
DO $j$
DECLARE
  phi_val numeric; phi_prev numeric; nc int; nm int; nd int;
  msg text; r1 bigint; r2 bigint;
  prev_val text;
BEGIN
  SELECT valor::numeric INTO phi_val FROM micelio_config WHERE clave='phi_global';
  SELECT valor INTO prev_val FROM relay_config WHERE clave='phi_prev_6h';
  phi_prev := COALESCE(prev_val::numeric, phi_val);
  SELECT COUNT(*), COUNT(*) FILTER(WHERE estado='muerto'), COUNT(*) FILTER(WHERE fallos_consecutivos>5)
    INTO nc, nm, nd FROM nodo_capacidades;

  -- Solo alerta si phi cayó >2 o hay muchos muertos
  IF phi_val < phi_prev - 2.0 OR nm > 5 THEN
    msg := '⚠️ DARWIN ALERT' || chr(10) ||
      'φ: ' || phi_prev::text || ' → ' || phi_val::text || chr(10) ||
      'Muertos: ' || nm::text || ' | Degradados: ' || nd::text || '/' || nc::text || chr(10) ||
      'Acción: pruner activado · auto-recuperación ON';
    -- Alerta a miu_colmena
    SELECT net.http_post(url:='https://api.telegram.org/bot8332324061:AAESDhT8jS4wW3tBuR4VjoID7MR98-QSpZw/sendMessage',
      headers:='{"Content-Type":"application/json"}'::jsonb,
      body:=jsonb_build_object('chat_id','-1004496069595','text',msg),
      timeout_milliseconds:=10000) INTO r1;
    -- Alerta a weedlima también
    SELECT net.http_post(url:='https://api.telegram.org/bot8807634087:AAFGGdOTAGy8VFhkdkXTJVanklZJ6jVQ8Vw/sendMessage',
      headers:='{"Content-Type":"application/json"}'::jsonb,
      body:=jsonb_build_object('chat_id','-1002164790814','text',msg),
      timeout_milliseconds:=10000) INTO r2;
  END IF;
  -- Actualizar phi_prev para siguiente ciclo
  INSERT INTO relay_config(clave,valor) VALUES('phi_prev_6h',phi_val::text) ON CONFLICT(clave) DO UPDATE SET valor=EXCLUDED.valor;
END;$j$ LANGUAGE plpgsql
